/** Generated by scripts/generators/build-temporary-attack-effects.cjs (game-data/temporary-attack-effects.json). */
export interface TemporaryAttackCatalog {
  effects:Record<string,{source:string;duration:number|null;modifiers:{attribute:string;elements:string[];kind:'percent'|'flat';magnitude:number|null}[]}>;
  /** Exact raw food classes and the permitted shots; retained in the build's ATK totals. */
  allowed?:Record<string,{kind:'food'|'injection';rows:string[]}>;
}
export interface CapturedEffect {definition:string;stackCount:number|null;durationSeconds:number|null}

/**
 * The profile ATK is a login snapshot (source observation), so temporary ATK effects active at login inflate it.
 * Constant ATK% is removed per element; flat ATK or an unknown magnitude makes the capture unusable.
 */
export function temporaryAttackAtCapture(records:readonly CapturedEffect[],catalog:TemporaryAttackCatalog) {
  const percent:Record<string,number>={},sources:string[]=[],blocking:string[]=[];
  for(const record of records) {
    if(catalog.allowed?.[record.definition])continue;
    const effect=record.durationSeconds!==null?catalog.effects[record.definition]:undefined;
    if(!effect)continue;
    const stacks=Math.max(1,record.stackCount??1);
    let usable=true;
    for(const modifier of effect.modifiers) {
      if(modifier.kind!=='percent'||modifier.magnitude===null){usable=false;continue;}
      for(const element of modifier.elements)percent[element]=(percent[element]??0)+modifier.magnitude*stacks;
    }
    (usable?sources:blocking).push(record.definition);
  }
  return {percent,sources,blocking};
}
